pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract ReenterOnce is Test {
    ReentrancyDAO public c;
    bool private __entered;

    constructor(ReentrancyDAO _c) { c = _c; }

    receive() external payable {
        if (!__entered) {
            __entered = true;
            c.withdrawAll();
        }
    }
}

contract InvMutTest is Test {
    ReentrancyDAO c;

    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(uint256 amount, uint256 seed) public {
        vm.assume(amount <= VALUE_CAP);
        amount = bound(amount, 1, type(uint96).max);
        ReenterOnce reenter = new ReenterOnce(c);
        vm.deal(address(reenter), amount);

        vm.prank(address(reenter));
        c.deposit{value: amount}();

        uint256 balBefore = address(c).balance;

        vm.prank(address(reenter));
        c.withdrawAll();

        bool secondWithdrawSucceeded = false;
        if (address(c).balance >= amount) {
            vm.prank(address(reenter));
            try c.withdrawAll() { secondWithdrawSucceeded = true; } catch {}
        }

        assertTrue(!secondWithdrawSucceeded);
    }
}
